         // 管理服务前端代码(一般将UI和SERVICE放到一个工程中，便于管理)\\n    |- servicex-auth     // 模块1\\n    |- servicex-common   // 模块2\\n    |- servicex-gateway  // 模块3\\n    |- servicex-system   // 模块4\\n        |- src\\n            |- main                  // 业务逻辑\\n                |- assembly          // 基于maven assembly插件的服务化打包方案\\n                    |- bin           // 模块脚本(启动、停止、重启)\\n                    |- sbin          // 管理员角色使用的脚本(环境检查、系统检测等等)\\n                    |- assembly.xml  // 配置文件\\n                |- java              // 源码\\n                    |- com\\n                        |- hadoopx\\n                            |- servicex\\n                                |- system\\n                                    |- annotation     // 注解\\n                                    |- aspect         // 面向切面编程\\n                                    |- config         // 配置文件POJO\\n                                    |- filter         // 过滤器\\n                                    |- constant       // 存放常量\\n                                    |- utils          // 工具\\n                                    |- exception      // 异常\\n                                    |- controller     // 控制层(将请求通过URL匹配，分配到不同的接收器/方法进行处理，然后返回结果)\\n                                    |- service        // 服务层接口\\n                                        |- impl       // 服务层实现\\n                                    |- mapper/repository // 数据访问层，与数据库交互为service提供接口\\n                                    |- entity/domain     // 实体对象\\n                                        |- dto // 持久层需要的实体对象(用于服务层与持久层之间的数据传输对象)\\n                                        |- vo // 视图层需要的实体对象(用于服务层与视图层之间的数据传输对象)\\n                                    |- *Application.java  // 入口启动类\\n                |- resources         // 资源\\n                    |- static        // 静态资源(html、css、js、图片等)\\n                    |- templates     // 视图模板(jsp、thymeleaf等)\\n                    |- mapper        // 存放数据访问层对应的XML配置\\n                        |- *Mapper.xml\\n                        |- ...\\n                    |- application.yml        // 公共配置\\n                    |- application-dev.yml    // 开发环境配置\\n                    |- application-prod.yml   // 生产环境配置\\n                    |- banner.txt    \\n                    |- logback.xml            // 日志配置\\n            |- test                  // 测试源码\\n               |- java               \\n                    |- com\\n                        |- hadoopx\\n                            |- servicex\\n                                |- system\\n                                    |- 根据具体情况按源码目录结构存放编写的测试用例\\n        |- target     // 编译打包输出目录(自动生成，不需要创建)\\n        |- pom.xml    // 该模块的POM文件\\n    |- sql            // 项目需要的SQL脚本\\n    |- doc            // 精简版的开发、运维手册\\n    |- .gitignore     // 哪些文件不用传到版本管控工具中\\n    |- pom.xml        // 工程总POM文件\\n    |- README.md      // 注意事项\\nExternal Libraries    // 相关JAR包依赖\\n\\n</code></pre><div class=\\"line-numbers\\" aria-hidden=\\"true\\"><div class=\\"line-number\\"></div><div class=\\"line-number\\"></div><div class=\\"line-number\\"></div><div class=\\"line-number\\"></div><div class=\\"line-number\\"></div><div class=\\"line-number\\"></div><div class=\\"line-number\\"></div><div class=\\"line-number\\"></div><div class=\\"line-number\\"></div><div class=\\"line-number\\"></div><div class=\\"line-number\\"></div><div class=\\"line-number\\"></div><div class=\\"line-number\\"></div><div class=\\"line-number\\"></div><div class=\\"line-number\\"></div><div class=\\"line-number\\"></div><div class=\\"line-number\\"></div><div class=\\"line-number\\"></div><div class=\\"line-number\\"></div><div class=\\"line-number\\"></div><div class=\\"line-number\\"></div><div class=\\"line-number\\"></div><div class=\\"line-number\\"></div><div class=\\"line-number\\"></div><div class=\\"line-number\\"></div><div class=\\"line-number\\"></div><div class=\\"line-number\\"></div><div class=\\"line-number\\"></div><div class=\\"lin